 void powerPage(){head("GÜÇ VE PERFORMANS");LinearLayout c=card();c.addView(new GaugeView(this),new LinearLayout.LayoutParams(-1,dp(230)));LinearLayout r=new LinearLayout(this);power=metric(r,"Doğrulanmış Güç","— Sol/s");workers=metric(r,"Aktif Worker","—");c.addView(r);LinearLayout q=new LinearLayout(this);shares=metric(q,"Paylaşılan İş","—");network=metric(q,"Ağ","Bekleniyor");c.addView(q);c.addView(t("Geçerli / geçersiz pay ve ağ ayrıntıları yalnız sağlayıcı tarafından doğrulandığında gösterilir.",12,MUTED));Button adv=btn("GELİŞMİŞ AYARLAR");adv.setOnClickListener(v->settings());c.addView(adv);page.addView(c);refreshDevice();refreshPool();}
 void refreshPayoutHistory(){String base=baseUrl(),session=secureStore.get("licence_session"),worker=betaPrefs.getString("worker_id","");if(historyText==null)return;if(base==null||session==null){historyText.setText("Henüz doğrulanmış işlem yok");return;}io.submit(()->{try{HttpURLConnection c=openApi(base+"/payouts");c.setRequestProperty("Authorization","License "+session);c.setRequestProperty("X-Install-Id",worker);c.setRequestProperty("X-Worker-Id",worker);int code=c.getResponseCode();JSONObject j=new JSONObject(readApi(c,code));c.disconnect();if(code==200){JSONArray a=j.optJSONArray("payouts");StringBuilder out=new StringBuilder();if(a!=null)for(int n=0;n<Math.min(5,a.length());n++){JSONObject p=a.optJSONObject(n);if(p!=null)out.append(n==0?"":"\n").append("• ").append(p.optString("amountDisplay","—")).append(" USDT_TEST — ").append(p.optString("status","—"));}String v=out.length()==0?"Henüz doğrulanmış işlem yok":out.toString();runOnUiThread(()->{if(historyText!=null)historyText.setText(v);});}else runOnUiThread(()->historyText.setText("İşlem geçmişi kullanılamıyor"));}catch(Exception e){runOnUiThread(()->{if(historyText!=null)historyText.setText("Bağlantı kurulamadı");});}});}
String baseUrl(){String x=betaPrefs.getString("endpoint",BuildConfig.MARSX_API_BASE_URL).trim().replaceAll("/$","");return x.matches("https://[A-Za-z0-9._:-]+")?x:null;}
 HttpURLConnection openApi(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(7000);c.setReadTimeout(7000);c.setRequestMethod("GET");c.setRequestProperty("Accept","application/json");return c;}
 String readApi(HttpURLConnection c,int code)throws Exception{InputStream in=code>=400?c.getErrorStream():c.getInputStream();if(in==null)return "{}";StringBuilder b=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)b.append(l);}return b.toString();}
 void refreshMarsxAccount(){String base=baseUrl(),session=secureStore.get("licence_session"),worker=betaPrefs.getString("worker_id","");if(balance==null)return;if(base==null||session==null){balance.setText("0.000000 MARS-X");return;}io.submit(()->{try{HttpURLConnection c=openApi(base+"/account");c.setRequestProperty("Authorization","License "+session);c.setRequestProperty("X-Install-Id",worker);c.setRequestProperty("X-Worker-Id",worker);int code=c.getResponseCode();JSONObject j=new JSONObject(readApi(c,code));c.disconnect();if(code==200){String v=j.optString("availableDisplay","0.000000");runOnUiThread(()->{if(balance!=null)balance.setText(v+" MARS-X");});}}catch(Exception ignored){}});}
 void refreshReferral(TextView codeView,TextView stats){String base=baseUrl(),session=secureStore.get("auth_session"),worker=betaPrefs.getString("worker_id","");if(base==null||session==null){codeView.setText("Giriş yapınca davet kodu oluşur");stats.setText("Toplam davet: —\nDavet kazancı: —");return;}io.submit(()->{try{HttpURLConnection c=openApi(base+"/auth/me");c.setRequestProperty("Authorization","Bearer "+session);c.setRequestProperty("X-Install-Id",worker);int code=c.getResponseCode();JSONObject j=new JSONObject(readApi(c,code));c.disconnect();if(code==200&&j.optBoolean("ok")){JSONObject r=j.optJSONObject("referral");if(r!=null){String rc=r.optString("code","");int n=r.optInt("invitedCount",0);long units=r.optLong("rewardUnits",0);String rw=java.math.BigDecimal.valueOf(units,6).toPlainString();betaPrefs.edit().putString("referral_code",rc).putInt("referral_invited",n).putString("referral_reward",rw).apply();runOnUiThread(()->{codeView.setText(rc.isEmpty()?"Kod bekleniyor":rc);stats.setText("Toplam davet: "+n+"\nDavet kazancı: "+rw+" MARS-X");});}}}catch(Exception ignored){}});}
void loadHistory(){loadSeries("hist_power",powerHistory);loadSeries("hist_temp",tempHistory);loadSeries("hist_latency",latencyHistory);loadTimes();}
 void loadSeries(String key,ArrayList<Float> out){out.clear();String raw=appPrefs.getString(key,"");if(raw.isEmpty())return;for(String x:raw.split(",")){try{out.add(Float.parseFloat(x));}catch(Exception ignored){}}while(out.size()>96)out.remove(0);}
 void addSample(String key,ArrayList<Float> out,float value){if(Float.isNaN(value)||Float.isInfinite(value)||value<0)return;out.add(value);while(out.size()>96)out.remove(0);StringBuilder b=new StringBuilder();for(Float x:out){if(b.length()>0)b.append(',');b.append(x);}appPrefs.edit().putString(key,b.toString()).apply();}
 void loadTimes(){telemetryTimes.clear();String raw=appPrefs.getString("hist_times","");if(!raw.isEmpty())for(String x:raw.split(","))try{telemetryTimes.add(Long.parseLong(x));}catch(Exception ignored){}}
 void stampTelemetry(){long now=System.currentTimeMillis();if(!telemetryTimes.isEmpty()&&now-telemetryTimes.get(telemetryTimes.size()-1)<25000)return;telemetryTimes.add(now);while(telemetryTimes.size()>96)telemetryTimes.remove(0);StringBuilder b=new StringBuilder();for(Long x:telemetryTimes){if(b.length()>0)b.append(',');b.append(x);}appPrefs.edit().putString("hist_times",b.toString()).apply();}
void refreshDevice(){Intent i=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null)return;int level=i.getIntExtra(android.os.BatteryManager.EXTRA_LEVEL,-1),scale=i.getIntExtra(android.os.BatteryManager.EXTRA_SCALE,100),raw=i.getIntExtra(android.os.BatteryManager.EXTRA_TEMPERATURE,-1);int pct=scale>0?Math.round(level*100f/scale):-1;float tc=raw>=0?raw/10f:-1;if(battery!=null)battery.setText("Pil alt limiti %"+appPrefs.getInt("battery_limit",15)+"  •  Cihaz pili "+(pct<0?"—":pct+"%"));int lim=appPrefs.getInt("thermal_limit",43);if(temp!=null)temp.setText(tc<0?lim+"°C sınır":String.format(Locale.getDefault(),"%.1f°C / %d°C",tc,lim));if(tc>=0)addSample("hist_temp",tempHistory,tc);}
 void refreshPool(){final String addr=poolPrefs.getString("address","");if(!VrscAddress.valid(addr)){if(network!=null)network.setText("Havuz verisi • Adres yapılandırılmadı");return;}if(network!=null)network.setText("Havuz verisi • Güncelleniyor…");final long t0=System.currentTimeMillis();io.submit(()->{try{LuckPoolClient.Snapshot x=pool.load(addr);long ms=System.currentTimeMillis()-t0;runOnUiThread(()->{stampTelemetry();addSample("hist_power",powerHistory,(float)x.hashrate);addSample("hist_latency",latencyHistory,(float)ms);if(power!=null)power.setText(String.format(Locale.getDefault(),"%,.2f Sol/s",x.hashrate));if(workers!=null){int n=0;for(LuckPoolClient.Worker w:x.workers)if(w.online)n++;workers.setText(String.valueOf(n));}if(shares!=null)shares.setText(x.shareValue);if(network!=null)network.setText("Sağlayıcı bağlantısı • "+ms+" ms");});}catch(Exception e){runOnUiThread(()->{if(network!=null)network.setText("Havuz verisi • Kullanılamıyor");});}});}
 public static class MiniMarkView extends View{Paint p=new Paint(1);public MiniMarkView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(ORANGE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(3,w*.08f));c.drawCircle(w/2,h/2,w*.35f,p);p.setStyle(Paint.Style.FILL);Path m=new Path();m.moveTo(w*.2f,h*.72f);m.lineTo(w*.34f,h*.25f);m.lineTo(w*.5f,h*.52f);m.lineTo(w*.66f,h*.25f);m.lineTo(w*.8f,h*.72f);m.lineTo(w*.66f,h*.72f);m.lineTo(w*.61f,h*.49f);m.lineTo(w*.5f,h*.68f);m.lineTo(w*.39f,h*.49f);m.lineTo(w*.34f,h*.72f);m.close();c.drawPath(m,p);}} public static class EmblemView extends View{Paint p=new Paint(1);public EmblemView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStyle(Paint.Style.FILL);p.setColor(ORANGE);Path m=new Path();m.moveTo(w*.15f,h*.82f);m.lineTo(w*.30f,h*.18f);m.lineTo(w*.50f,h*.57f);m.lineTo(w*.70f,h*.18f);m.lineTo(w*.85f,h*.82f);m.lineTo(w*.68f,h*.82f);m.lineTo(w*.63f,h*.50f);m.lineTo(w*.50f,h*.78f);m.lineTo(w*.37f,h*.50f);m.lineTo(w*.32f,h*.82f);m.close();c.drawPath(m,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(4,w*.018f));RectF r=new RectF(w*.10f,h*.32f,w*.90f,h*.70f);c.save();c.rotate(-14,w/2,h/2);c.drawOval(r,p);c.restore();}} public static class GaugeView extends View{Paint p=new Paint(1);public GaugeView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),cx=w/2,cy=h*.62f,r=Math.min(w,h)*.38f;p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(Math.max(16,w*.055f));p.setColor(Color.rgb(55,31,18));RectF a=new RectF(cx-r,cy-r,cx+r,cy+r);c.drawArc(a,150,240,false,p);p.setColor(ORANGE);c.drawArc(a,150,120,false,p);p.setStyle(Paint.Style.FILL);p.setColor(WHITE);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(w*.11f);c.drawText("⚡",cx,cy,p);p.setTextSize(w*.05f);p.setColor(MUTED);c.drawText("DOĞRULANMIŞ GÜÇ",cx,cy+h*.15f,p);}} public static class MarsView extends View{Paint p=new Paint(1);public MarsView(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),cx=w/2,cy=h*.48f,r=Math.min(w,h)*.31f;p.setStyle(Paint.Style.FILL);p.setShader(new RadialGradient(cx-r*.3f,cy-r*.35f,r*1.4f,new int[]{Color.rgb(255,151,55),Color.rgb(181,54,12),Color.rgb(40,8,5)},null,Shader.TileMode.CLAMP));c.drawCircle(cx,cy,r,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(5,w*.018f));p.setColor(ORANGE);RectF o=new RectF(cx-r*1.35f,cy-r*.45f,cx+r*1.35f,cy+r*.45f);c.save();c.rotate(-18,cx,cy);c.drawOval(o,p);c.restore();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(3,w*.009f));p.setStrokeCap(Paint.Cap.ROUND);for(int i=0;i<18;i++){p.setColor(i<12?ORANGE:Color.rgb(55,30,18));float a=(float)Math.toRadians(-210+i*14);float rr=r*1.42f;float x1=cx+(float)Math.cos(a)*rr,y1=cy+(float)Math.sin(a)*rr;float x2=cx+(float)Math.cos(a)*(rr+r*.13f),y2=cy+(float)Math.sin(a)*(rr+r*.13f);c.drawLine(x1,y1,x2,y2,p);}p.setStyle(Paint.Style.FILL);p.setColor(Color.argb(90,0,0,0));c.drawCircle(cx+r*.28f,cy-r*.16f,r*.13f,p);c.drawCircle(cx-r*.25f,cy+r*.2f,r*.09f,p);}}
 public static class EmptyChartView extends View{Paint p=new Paint(1);String label;public EmptyChartView(Context c,String l){super(c);label=l;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStrokeWidth(1);p.setColor(Color.rgb(36,40,45));for(int i=1;i<5;i++)c.drawLine(0,h*i/5,w,h*i/5,p);for(int i=1;i<7;i++)c.drawLine(w*i/7,0,w*i/7,h*.82f,p);p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setColor(MUTED);p.setTextSize(Math.max(13,w*.038f));c.drawText(label,w/2,h*.43f,p);p.setTextSize(Math.max(12,w*.033f));c.drawText("Doğrulanmış veri bekleniyor",w/2,h*.58f,p);}}
 public static class HistoryChartView extends View{Paint p=new Paint(1);List<Float>[] series;List<Long> times;String period;float touchX=-1;@SuppressWarnings("unchecked") public HistoryChartView(Context c,List<Float>a,List<Float>b,List<Float>d,List<Long>t,String pr){super(c);series=new List[]{a,b,d};times=t;period=pr;setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN||e.getAction()==MotionEvent.ACTION_MOVE){touchX=e.getX();invalidate();return true;}return false;});}long window(){if("Haftalık".equals(period))return 7L*86400000;if("Aylık".equals(period))return 30L*86400000;if("Tümü".equals(period))return Long.MAX_VALUE;return 86400000;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),left=w*.13f,right=w*.97f,top=h*.08f,bottom=h*.78f;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(Color.rgb(37,40,45));for(int i=0;i<5;i++){float y=top+(bottom-top)*i/4;c.drawLine(left,y,right,y,p);}int count=Math.min(times.size(),Math.min(series[0].size(),series[2].size()));long cutoff=System.currentTimeMillis()-window();int first=0;while(first<count&&times.get(first)<cutoff)first++;if(count-first<2){empty(c,w,h);return;}String[] units={"Sol/s","°C","ms"};int[] cs={ORANGE,Color.rgb(245,66,83),Color.rgb(55,155,255)};float[] maxs={1,1,1};for(int k=0;k<3;k++)for(int i=first;i<Math.min(count,series[k].size());i++)maxs[k]=Math.max(maxs[k],series[k].get(i));for(int k=0;k<3;k++){List<Float>a=series[k];if(a.size()<count)continue;p.setColor(cs[k]);p.setStrokeWidth(4);Path q=new Path();for(int i=first;i<count;i++){float x=left+(right-left)*(i-first)/Math.max(1f,count-first-1);float y=bottom-(a.get(i)/maxs[k])*(bottom-top);if(i==first)q.moveTo(x,y);else q.lineTo(x,y);}c.drawPath(q,p);}p.setStyle(Paint.Style.FILL);p.setTextSize(w*.029f);p.setTextAlign(Paint.Align.LEFT);for(int k=0;k<3;k++){p.setColor(cs[k]);c.drawText(units[k]+" max "+fmt(maxs[k]),left+k*w*.27f,h*.9f,p);}long age=System.currentTimeMillis()-times.get(count-1);p.setColor(age>300000?Color.rgb(255,170,40):MUTED);p.setTextAlign(Paint.Align.RIGHT);c.drawText(age<60000?"Şimdi":(age/60000)+" dk önce",right,h*.97f,p);if(touchX>=left&&touchX<=right){int idx=first+Math.round((touchX-left)/(right-left)*(count-first-1));idx=Math.max(first,Math.min(count-1,idx));float x=left+(right-left)*(idx-first)/Math.max(1f,count-first-1);p.setColor(WHITE);p.setStrokeWidth(2);c.drawLine(x,top,x,bottom,p);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(w*.032f);String tm=new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(new java.util.Date(times.get(idx)));c.drawText(tm+"  "+fmt(series[0].get(idx))+" Sol/s  "+fmt(series[2].get(idx))+" ms",Math.min(right-w*.25f,Math.max(left+w*.25f,x)),top+h*.06f,p);}}void empty(Canvas c,float w,float h){p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setColor(MUTED);p.setTextSize(w*.042f);c.drawText("Doğrulanmış veri bekleniyor",w/2,h/2,p);}String fmt(float v){return v>=1000?String.format(Locale.getDefault(),"%.1fk",v/1000f):String.format(Locale.getDefault(),"%.1f",v);}}
 @Override protected void onDestroy(){pool.cancel();io.shutdownNow();timer.removeCallbacksAndMessages(null);super.onDestroy();}
